// Content names -> logo. Names without a logo render as plain text chips.
const byName: Record<string, string> = {
  "AWS": "aws",
  "Google Cloud": "googlecloud",
  "GCP": "googlecloud",
  "Kubernetes": "kubernetes",
  "Kubernetes CRDs": "kubernetes",
  "CRDs and Operators": "kubernetes",
  "Helm": "helm",
  "Argo CD": "argo",
  "NGINX Ingress": "nginx",
  "NGINX": "nginx",
  "Docker": "docker",
  "Pulumi": "pulumi",
  "Terraform": "terraform",
  "GitLab CI": "gitlab",
  "Jenkins": "jenkins",
  "Spinnaker": "spinnaker",
  "Rancher Fleet": "rancher",
  "JFrog Artifactory": "jfrog",
  "Prometheus": "prometheus",
  "Grafana": "grafana",
  "HashiCorp Vault": "vault",
  "Vault": "vault",
  "Cloudflare": "cloudflare",
  "Python": "python",
  "FastAPI": "fastapi",
  "Celery": "celery",
  "Go": "go",
  "Bash": "gnubash",
  "Groovy": "apachegroovy",
  "Kafka": "apachekafka",
  "Redis": "redis",
  "MongoDB": "mongodb",
  "ScyllaDB": "scylladb",
  "Checkmarx": "checkmarx",
};

export const logoFor = (name: string): Logo | undefined => logos[byName[name]];
